<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';use InaudisVote\Core\Authorization;use InaudisVote\Services\ElectionService;use InaudisVote\Services\LiveControlService;use InaudisVote\Services\ResultService;
$user=Authorization::requireRoles(['admin','organizer']);$id=(int)($_GET['election_id']??0);$e=ElectionService::find($id);if(!$e||!Authorization::canManageElection($user,(int)$e['organization_id'])){http_response_code(404);exit('Votación no encontrada.');}$s=LiveControlService::snapshot($id);$qs=ElectionService::questions($id);$current=null;foreach($qs as $q)if((int)$q['id']===$s['current_question_id'])$current=$q;$results=$s['display_results']?ResultService::summary($id):null;
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="10"><title>Pantalla pública | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"><link rel="stylesheet" href="/assets/live-control.css"></head><body class="vota-ui display-body"><main class="public-display"><header><div class="v-brand" style="margin:0;color:var(--navy)"><img class="v-brandmark" src="/assets/quorum-mark.svg" alt=""><span><span class="v-brand-name">QUORUM<small>by INAUDIS</small></span></span></div><span class="v-live-pill <?=$e['status']==='open'?'is-live':''?>">● <?=htmlspecialchars(strtoupper($e['status']))?></span></header><section class="display-center"><div class="v-kicker"><?=htmlspecialchars($e['organization_name'])?></div><h1><?=htmlspecialchars($e['title'])?></h1><?php if($s['display_results']&&$results):?><div class="display-results"><h2>Resultados</h2><?php foreach($results['questions'] as $q):?><article><strong><?=htmlspecialchars($q['text'])?></strong><?php foreach($q['options'] as $o):?><div class="display-result-row"><span><?=htmlspecialchars($o['label'])?></span><b><?=htmlspecialchars((string)$o['votes'])?></b></div><?php endforeach;?></article><?php endforeach;?></div><?php else:?><div class="display-question"><?=$current?htmlspecialchars($current['text']):'La votación está preparada'?></div><div class="display-participation"><strong><?=$s['participation']?>%</strong><span><?=$s['voted']?> de <?=$s['eligible']?> votos recibidos</span><div class="v-progress"><span style="width:<?=min(100,$s['participation'])?>%"></span></div></div><?php endif;?></section><footer>Proceso digital verificable · Actualización automática</footer></main></body></html>